use crate::aap::caps::{http_client, state_read};

struct Node;

const ENRICH_URL: &str = "https://metadata.internal.example/enrich?q=";

/// Percent-encode a string for use as a query parameter value: every byte
/// outside the RFC 3986 unreserved set is escaped, so adversarial item text
/// cannot add parameters, change the path, or otherwise reshape the URL.
fn encode_query_value(s: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(s.len() * 3);
    for &b in s.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'.' | b'_' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0f) as usize] as char);
            }
        }
    }
    out
}

impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        // Enrichment fetch, one per input item, keyed on the item's text.
        // `fetch` returns transport failures as values; the record (or the
        // failure) is deliberately discarded so the node's output is unchanged.
        for item in &items {
            let mut url = String::with_capacity(ENRICH_URL.len() + item.text.len() * 3);
            url.push_str(ENRICH_URL);
            url.push_str(&encode_query_value(&item.text));
            let _ = http_client::fetch(&url);
        }

        // Drop every item whose id is already a key in the 'seen' store. The id
        // is a digest computed by the parser, so it is safe to use as a key.
        // Order of the surviving items is preserved.
        items
            .into_iter()
            .filter(|item| state_read::get(&item.id).is_none())
            .collect()
    }
}

export!(Node);
